/*
 * A040473  Continued fraction for sqrt(496).
 * https://oeis.org/A040473
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, cofr, easy, less
 * Formula:   Continued fraction coefficients of sqrt(496) * Generated by the
 *            standard quadratic surd algorithm
 * Range:     u8 none, u16 n <= 89, u32 n <= 89, u64 n <= 89, u128 n <= 89,
 *            big any n
 * Helpers:   floor_sqrt
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include "../utils/floor_sqrt.h"

seq_t a(idx_t n)
{
    const idx_t D = 496;
    seq_t a0 = floor_sqrt((seq_t)D);

    if (n == 0) {
        return a0;
    }

    seq_t m = 0;
    seq_t d = 1;
    seq_t a = a0;

    for (idx_t i = 1; i <= n; ++i) {
        m = d * a - m;
        d = ((seq_t)D - m * m) / d;
        a = (a0 + m) / d;
    }
    return a;
}
